<template><div class="search-page"><div class="search-bar"><el-input v-model="keyword" placeholder="搜索商品" @keyup.enter="doSearch"><template #append><el-button @click="doSearch">搜索</el-button></template></el-input></div><div class="hot-search"><div class="title">热门搜索</div><div class="tags"><el-tag v-for="item in hotList" :key="item" @click="keyword=item;doSearch()" style="margin:5px">{{ item }}</el-tag></div></div><div class="result" v-if="list.length"><div class="goods-grid"><div v-for="item in list" :key="item.id" class="goods-item" @click="$router.push('/product/'+item.id)"><el-image :src="item.main_image" fit="cover" style="width:100%;height:150px"/><div class="name">{{ item.name }}</div><div class="price">¥{{ item.price }}</div></div></div></div></div></template><script setup>import{ref,onMounted}from'vue';import request from'@/utils/request';const keyword=ref('');const list=ref([]);const hotList=ref(['手机','电脑','服装','美食','美妆']);const doSearch=async()=>{if(!keyword.value)return;const res=await request({url:'/products',params:{keyword:keyword.value}});list.value=res.data?.list||res.data||[]};onMounted(async()=>{const res=await request({url:'/hot-searches'});if(res.data&&res.data.length)hotList.value=res.data.map(i=>i.keyword)})</script><style scoped>.search-page{padding:15px}.search-bar{margin-bottom:20px}.hot-search .title{font-size:14px;color:#909399;margin-bottom:10px}.goods-grid{display:grid;grid-template-columns:repeat(2,1fr);gap:10px}.goods-item{background:#fff;border-radius:8px;overflow:hidden}.goods-item .name{font-size:13px;padding:8px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.goods-item .price{color:#f56c6c;font-weight:bold;padding:0 8px 8px}</style>
